<?php
require_once __DIR__ . '/_event_helpers.php';
header('Content-Type: application/json');
try{$ownerId=(int)($_GET['user_id']??0);if($ownerId<=0)throw new InvalidArgumentException('User ID is required');$db=event_db();$statement=$db->prepare("SELECT id,user_id,event_type,title,message,media_path,media_mime,media_type,scheduled_date,privacy_level,status,created_at FROM scheduled_events WHERE user_id=:owner AND status IN ('scheduled','published','cancelled') ORDER BY scheduled_date ASC");$statement->execute(['owner'=>$ownerId]);$viewerId=SessionHelper::getUserId();$events=array_values(array_filter($statement->fetchAll(PDO::FETCH_ASSOC),static function(array $event)use($db,$viewerId){return event_can_view($db,$event,$viewerId);}));foreach($events as &$event){$event['id']=(int)$event['id'];$event['user_id']=(int)$event['user_id'];$event['media_url']=!empty($event['media_path'])?'/backend/events/media.php?event_id='.$event['id']:null;unset($event['media_path']);}unset($event);echo json_encode(['success'=>true,'events'=>$events,'count'=>count($events)]);}
catch(Throwable $error){error_log('List events error: '.$error->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Error loading events']);}
